import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-moves-a-task-on-the-board', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  await test.step('action: create', async () => {
    await app.action('create');
  });
  await test.step('fill: {title: Move on the board}', async () => {
    await app.fill({ title: 'Move on the board' });
  });
  await test.step('submit', async () => {
    await app.submit({ saved: true });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
  await test.step('open: task-board', async () => {
    await app.open('task-board');
  });
  await test.step('move: {where: {title: Move on the board}, to: in_progress}', async () => {
    await app.move({ where: { title: 'Move on the board' }, to: 'in_progress' });
  });
  await test.step('open_item: {where: {title: Move on the board}}', async () => {
    await app.openItem({ where: { title: 'Move on the board' } });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: in_progress}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('in_progress');
  });
});
